import appLogger from '@/utils/logger/app-logger';

class Configuration {
  public getClientId(): string {
    const clientId = import.meta.env.IDENTITY_PROVIDER_APP_CLIENT_ID;
    if (!clientId) {
      throw new Error('CLIENT_ID not found in environment variables.');
    }
    return clientId;
  }

  public getAuthority(): string {
    const authority = import.meta.env.IDENTITY_PROVIDER_APP_AUTHORITY;
    if (!authority) {
      throw new Error('AUTHORITY not found in environment variables.');
    }
    appLogger.debug(this);
    return authority;
  }

  public getRedirectUri(): string {
    const redirectUri = import.meta.env.APP_REDIRECT_URI;
    if (!redirectUri) {
      throw new Error('REDIRECT_URI not found in environment variables.');
    }
    return redirectUri;
  }

  public getScopes(): string {
    const scopes = import.meta.env.IDENTITY_PROVIDER_APP_SCOPES;
    if (!scopes) {
      throw new Error('SCOPES not found in environment variables.');
    }
    appLogger.debug(this);
    return scopes;
  }

  public getResponseType(): string {
    appLogger.debug(this);
    const code = import.meta.env.IDENTITY_PROVIDER_APP_RESPONSE_TYPE;
    return code;
  }

  public getAccessTokenExpiringNotificationTime(): number {
    appLogger.debug(this);
    const value =
      import.meta.env.ACCESS_TOKEN_EXPIRING_REFRESH_SECONDS || '1800';
    return Number.parseInt(value, 10);
  }
}

const configuration = new Configuration();

export { configuration };

import {
  authenticateUser,
  authorizeUser,
  AuthConfigService,
  ApiService,
  extractGroupNames,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { User, WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
import { useRouter } from 'vue-router';
import { configuration } from '@/Auth/configuration.ts';
import { AuthConfigDTO } from '@/types/auth.config.dto.ts';
import appLogger from '@/utils/logger/app-logger';

interface State {
  profile: string;
  userAttributes: { [key: string]: string };
  isLeader: boolean;
}

const authconfig = new AuthConfigDTO(
  configuration.getAuthority(),
  configuration.getClientId(),
  configuration.getRedirectUri(),
  configuration.getResponseType(),
  configuration.getScopes(),
  new WebStorageStateStore({ store: window.sessionStorage }),
  configuration.getAccessTokenExpiringNotificationTime(),
);
const umeBaseUrl = import.meta.env.UME_API_URL;
const appName = 'BUFFER-MONITORING';
let tokenEnvironment = import.meta.env.TOKEN;
tokenEnvironment =
  tokenEnvironment === 'PING_FEDERATE'
    ? sessionStorage.getItem('id_token')
    : tokenEnvironment;
const pickingRedirectUri = import.meta.env.PICKING_APP_REDIRECT_URI;
let appBasePath: string;
if (pickingRedirectUri) {
  const parts = pickingRedirectUri.split('/');
  appBasePath = parts.pop();
}
const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, tokenEnvironment, appName);
const userAttributesManager = new UserAttributesManager(apiService);
export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser() {
      await authenticateUser(authService, apiService);
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await authService.getUser();
      if (user) {
        const groupNames = await extractGroupNames(user.profile.groups);
        const roleNamesString = groupNames.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes =
          userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes) {
          this.userAttributes = { ...userAttributes };
        } else {
          appLogger.warn('No user attributes found.');
        }
      } catch (error) {
        appLogger.error(`Error fetching user attributes: ${error}`);
      }
    },
    async getUser(): Promise<User | null> {
      return authService.getUser();
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
        await authService.logout();
      } catch {
        appLogger.error('Log out failed');
      }
    },
    async refreshToken() {
      await authService.refreshToken();
    },
    async tryToBecomeLeader(): Promise<boolean> {
      const isLeader = await authService.becomeLeaderIfElected();
      this.isLeader = isLeader;
      return isLeader;
    },

    async requestTokenFromLeader() {
      return authService.requestTokenFromLeader();
    },
  },

  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    profile: '',
    userAttributes: {} as { [key: string]: string },
    isLeader: false,
  }),
  getters: {
    tokenChannel: () => authService.getTokenChannel(),
    userManager: () => authService.getUserManager(),
  },
});

